const assert = require('assert');
const UsesOptimizedImagesAudit = require('../../../audits/byte-efficiency/uses-optimized-images.js');

function generateImage(type, originalSize, webpSize, jpegSize) {
  return {
    url: `http://example.com/image.${type}`,
    mimeType: `image/${type}`,
    originalSize, webpSize, jpegSize,
  };
}

describe('Page uses optimized images', () => {
  it('flags BMP images for next-gen formats', () => {
    const auditResult = UsesOptimizedImagesAudit.audit_({
      OptimizedImages: [
        generateImage('bmp', 12000, 6000, 8000),
      ],
    });

    assert.equal(auditResult.items.length, 1);
    assert.ok(/image.bmp/.test(auditResult.items[0].url));
  });
});
